const cp = require('child_process');
const parent = Number(process.env.WA_REAP_PARENT);
const child = Number(process.env.WA_REAP_CHILD);
const win = process.platform === 'win32';
const alive = (p) => { try { process.kill(p, 0); return true; } catch (e) { return e.code === 'EPERM'; } };

function isBrowser(pid) {
  try {
    if (win) {
      const out = cp.spawnSync('tasklist', ['/FI', 'PID eq ' + pid, '/FO', 'CSV', '/NH'],
        { encoding: 'utf8', windowsHide: true, timeout: 5000 }).stdout || '';
      return /^"(chrome|chromium|msedge|brave)\\.exe"/i.test(out.trim());
    }
    const out = cp.spawnSync('ps', ['-o', 'comm=', '-p', String(pid)],
      { encoding: 'utf8', timeout: 5000 }).stdout || '';
    return /chrom|brave|edge/i.test(out);
  } catch (e) { return false; }
}

function reap() {
  if (child && alive(child) && isBrowser(child)) {
    try {
      if (win) {
        cp.spawnSync('taskkill', ['/PID', String(child), '/T', '/F'], { windowsHide: true, timeout: 8000 });
      } else {
        try { process.kill(-child, 'SIGKILL'); } catch (e) { process.kill(child, 'SIGKILL'); }
      }
    } catch (e) { /* it exited between the check and the kill */ }
  }
  stop();
}

if (!parent || !child) process.exit(0);

process.stdin.resume();
process.stdin.on('end', reap);
process.stdin.on('close', reap);
process.stdin.on('error', reap);

const timer = setInterval(() => {
  if (!alive(child)) return stop();   // the browser is already gone
  if (alive(parent)) return;          // the server is still running
  reap();
}, 5000);

